int decodeAdpcmWavBlock(const uint8_t *encoded, int16_t *decoded) {
    // Initialize previous values and indices for each audio channel
    int16_t prev[2] = {0};
    int8_t index[2] = {0};

    // Read initial state for each channel from the encoded data
    prev[0] = *reinterpret_cast<const int16_t*>(encoded);
    index[0] = encoded[2];
    prev[1] = *reinterpret_cast<const int16_t*>(encoded + 3);
    index[1] = encoded[5];
    const uint8_t *data = encoded + 6;

    // ADPCM step size table
    const int stepTable[89] = {
        7, 8, 9, 10, 11, 12, 13, 14, 16, 17,
        19, 21, 23, 25, 28, 31, 34, 37, 41, 45,
        50, 55, 60, 66, 73, 80, 88, 97, 107, 118,
        130, 143, 157, 173, 190, 209, 230, 253, 279, 307,
        337, 371, 408, 449, 495, 545, 599, 658, 722, 791,
        866, 947, 1035, 1130, 1232, 1342, 1460, 1587, 1723, 1870,
        2027, 2195, 2375, 2568, 2775, 2996, 3232, 3485, 3756, 4047,
        4359, 4693, 5051, 5433, 5842, 6278, 6744, 7240, 7769, 8330,
        8926, 9560, 10235, 10953, 11717, 12530, 13396, 14318, 15300, 16345,
        17459, 18647, 19913, 21262, 22698, 24230, 25860, 27593, 29434, 31391,
        33472, 35685, 38037, 40535, 43187, 45999, 48983, 52144, 55494, 59041,
        62794, 66766, 70968, 75407, 79636, 84438, 89521, 94900, 100586, 106592,
        112930, 119615, 126658, 134078, 141890, 150008, 158473
    };

    // Output buffer index
    int outIndex = 0;

    // Process the encoded data
    while (*data) {
        for (int ch = 0; ch < 2; ++ch) {
            int step = stepTable[std::abs(index[ch])];
            int8_t nibble = *data >> (4 * ch);
            int delta = (nibble & 0x0F);

            // Adjust delta based on the nibble value
            if (delta & 0x08) {
                delta -= 0x10;
            }

            // Calculate new sample value
            int16_t sample = prev[ch] + delta * step;
            sample = std::max(std::min(sample, static_cast<int16_t>(32767)), static_cast<int16_t>(-32768));

            decoded[outIndex++] = sample;

            // Update previous value and index for the channel
            prev[ch] = sample;
            index[ch] += (delta * 2) - 1;
            index[ch] = std::max(std::min(index[ch], 7), -8);
        }

        // Move to the next byte
        ++data;
    }

    return outIndex * sizeof(int16_t);
}

